@import "tailwindcss";

/* "dark:"-Klassen greifen über die .dark-Klasse auf <html>, nicht über die
   Systemeinstellung — so kann der Umschalter (ThemeToggle) sie übersteuern. */
@custom-variant dark (&:where(.dark, .dark *));

/* BMW-Look: weiß/schwarz statt bunt, BMW-Blau (#1C69D4) als einzige Akzentfarbe,
   Flächen trennen sich über dünne Haarlinien statt über Farbe oder Schatten. */
:root {
  --background: #ffffff;
  --foreground: #1a1a1a;
  /* Hintergrund von Karten, Kopfzeile, Eingabefeldern — eine Stelle für alle Elemente */
  --surface: #ffffff;
  --accent: #1c69d4;
  --accent-hover: #164f9f;
}

.dark {
  --background: #0a0a0a;
  --foreground: #f2f2f2;
  --surface: #141414;
  --accent: #4a90e2;
  --accent-hover: #70aaee;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-surface: var(--surface);
  --color-accent: var(--accent);
  --color-accent-hover: var(--accent-hover);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-sans), Helvetica, Arial, sans-serif;
  transition: background-color 0.2s ease, color 0.2s ease;
}

/**
 * Horizontaler Balken für den Score (0-100) mit Zahl daneben, Akzentfarbe Blau
 * nach Design-Regel. Eigene Datei, weil Liste (D2) und Score-Wasserfall (D3)
 * dieselbe Balken-Optik brauchen.
 */
export function ScoreBar({ score }: { score: number }) {
  const width = Math.max(0, Math.min(100, score));
  return (
    <div className="flex items-center gap-2">
      <div className="h-2 w-28 overflow-hidden rounded-full bg-zinc-200 dark:bg-zinc-800">
        <div className="h-full rounded-full bg-accent" style={{ width: `${width}%` }} />
      </div>
      <span className="w-10 text-right text-sm font-medium text-foreground">
        {Math.round(score)}
      </span>
    </div>
  );
}

/**
 * Score-Wasserfall für die Detailseite (D3). Spiegelt die Formel aus
 * requirements_engine/scoring.py: score = Konfidenz(Evidenzstufe) * Summe(gewicht_i * faktor_i) * 100.
 * Die Konfidenzzahlen selbst (A=1.0 ... D=0.5) holen wir NICHT hierher, sondern rechnen den
 * Abzug aus Zwischensumme und Endscore zurück — sonst müssten zwei Stellen dieselbe Zahl pflegen.
 */
import type { EvidenceLevel, ScoreFactor } from "@/src/lib/api";

const FACTOR_ORDER = [
  "customer_pain",
  "reach",
  "satisfaction_gap",
  "competitive_pressure",
  "future_relevance",
  "effort_inverse",
] as const;

const FACTOR_LABELS: Record<string, string> = {
  customer_pain: "Customer pain",
  reach: "Reach",
  satisfaction_gap: "Satisfaction gap",
  competitive_pressure: "Competitive pressure",
  future_relevance: "Future relevance",
  effort_inverse: "Low effort",
};

const EVIDENCE_LABEL: Record<EvidenceLevel, string> = {
  A: "A · strong",
  B: "B · medium",
  C: "C · weak",
  D: "D · assumption",
};

function FactorRow({ label, factor }: { label: string; factor: ScoreFactor }) {
  // Balkenbreite relativ zum höchstmöglichen Beitrag dieses Faktors (weight * 100),
  // damit ein voll ausgeschöpfter Faktor immer einen vollen Balken zeigt.
  const maxContribution = Math.max(factor.weight * 100, 0.01);
  const width = Math.min(100, (factor.contribution / maxContribution) * 100);
  return (
    <div className="py-2">
      <div className="flex flex-wrap items-baseline justify-between gap-x-3 text-sm">
        <span className="font-medium text-[#0b1f3a] dark:text-zinc-100">{label}</span>
        <span className="text-zinc-500 dark:text-zinc-400">
          +{factor.contribution.toFixed(1)} pts
          <span className="ml-1 text-xs text-zinc-400 dark:text-zinc-500">
            ({factor.value.toFixed(2)} × {factor.weight.toFixed(2)} × 100)
          </span>
        </span>
      </div>
      <div className="mt-1 h-2 w-full overflow-hidden rounded-full bg-zinc-100 dark:bg-zinc-800">
        <div className="h-full rounded-full bg-accent" style={{ width: `${width}%` }} />
      </div>
      <p className="mt-1 text-xs text-zinc-500 dark:text-zinc-400">{factor.explanation}</p>
    </div>
  );
}

export function ScoreWaterfall({
  scoreBreakdown,
  evidenceLevel,
  finalScore,
}: {
  scoreBreakdown: Record<string, ScoreFactor>;
  evidenceLevel: EvidenceLevel;
  finalScore: number;
}) {
  const known = new Set<string>(FACTOR_ORDER);
  const orderedKeys = [
    ...FACTOR_ORDER.filter((key) => key in scoreBreakdown),
    ...Object.keys(scoreBreakdown).filter((key) => !known.has(key)),
  ];
  const subtotal = orderedKeys.reduce((sum, key) => sum + scoreBreakdown[key].contribution, 0);
  const deduction = Math.max(0, subtotal - finalScore);
  const keptPercent = subtotal > 0 ? Math.round((finalScore / subtotal) * 100) : 100;

  return (
    <div className="rounded-lg border border-zinc-200 bg-surface p-5 dark:border-zinc-800">
      <h2 className="text-sm font-semibold uppercase tracking-wide text-zinc-500 dark:text-zinc-400">Score breakdown</h2>
      <div className="mt-2 divide-y divide-zinc-100 dark:divide-zinc-800">
        {orderedKeys.map((key) => (
          <FactorRow key={key} label={FACTOR_LABELS[key] ?? key} factor={scoreBreakdown[key]} />
        ))}
      </div>

      <div className="mt-4 border-t border-dashed border-zinc-300 pt-3 dark:border-zinc-700">
        <div className="flex items-baseline justify-between text-sm">
          <span className="text-zinc-600 dark:text-zinc-400">Subtotal (all factors, full confidence)</span>
          <span className="font-medium text-[#0b1f3a] dark:text-zinc-100">{subtotal.toFixed(1)} pts</span>
        </div>
        {deduction > 0 && (
          <div className="mt-1 flex items-baseline justify-between text-sm">
            <span className="text-zinc-600 dark:text-zinc-400">
              Confidence deduction — evidence level {EVIDENCE_LABEL[evidenceLevel]} keeps {keptPercent}%
            </span>
            <span className="font-medium text-amber-700 dark:text-amber-400">-{deduction.toFixed(1)} pts</span>
          </div>
        )}
        <div className="mt-2 flex items-baseline justify-between border-t border-zinc-200 pt-2 text-base dark:border-zinc-800">
          <span className="font-semibold text-[#0b1f3a] dark:text-zinc-100">Final score</span>
          <span className="font-semibold text-[#0b1f3a] dark:text-zinc-100">{finalScore.toFixed(1)} / 100</span>
        </div>
      </div>
    </div>
  );
}

