"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import {
  getExportUrl,
  getRequirements,
  getScenarios,
  type Requirement,
  type Scenario,
} from "@/src/lib/api";
import { categoryLabel } from "@/src/components/badges";
import { ScoreBar } from "@/src/components/ScoreBar";
import { ThemeToggle } from "@/src/components/ThemeToggle";

const DEFAULT_SCENARIO_ID = "G60-US";

export default function RequirementsPage() {
  const router = useRouter();

  const [scenarios, setScenarios] = useState<Scenario[] | null>(null);
  const [scenarioId, setScenarioId] = useState<string>(DEFAULT_SCENARIO_ID);
  const [requirements, setRequirements] = useState<Requirement[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isFetching, setIsFetching] = useState(true);

  const [promptText, setPromptText] = useState("");
  const [promptNote, setPromptNote] = useState<string | null>(null);

  // Szenarien einmal laden; Standard bleibt G60-US, falls vorhanden, sonst erstes Szenario.
  useEffect(() => {
    getScenarios()
      .then((loaded) => {
        setScenarios(loaded);
        if (!loaded.some((s) => s.id === DEFAULT_SCENARIO_ID) && loaded[0]) {
          setScenarioId(loaded[0].id);
        }
      })
      .catch((err: Error) => setError(err.message));
  }, []);

  // Anforderungen neu laden bei Szenario-Wechsel.
  useEffect(() => {
    if (!scenarioId) return;
    let cancelled = false;
    (async () => {
      setIsFetching(true);
      try {
        const loadedRequirements = await getRequirements(scenarioId);
        if (cancelled) return;
        setRequirements(loadedRequirements);
        setError(null);
      } catch (err) {
        if (cancelled) return;
        setError((err as Error).message);
      } finally {
        if (!cancelled) setIsFetching(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [scenarioId]);

  const isLoading = scenarios === null || isFetching || requirements === null;

  /** Platzhalter: Das Prompt-Feld ist noch nicht ans Backend angebunden (eigenes Ticket). */
  function handlePromptSubmit() {
    const text = promptText.trim();
    if (!text) return;
    console.log("[prompt submit - placeholder, not wired to backend yet]", text);
    setPromptNote(`Received: "${text}" — not connected to the backend yet.`);
    setPromptText("");
  }

  return (
    <div className="flex min-h-screen flex-col">
      {/* Top bar: volle Breite, nach BMW-Vorbild schlicht weiß/schwarz mit dünner Haarlinie statt Schatten.
          Sticky, damit sie beim Scrollen der Seite oben bleibt. */}
      <header className="sticky top-0 z-10 w-full border-b border-zinc-200 bg-surface dark:border-zinc-800">
        <div className="flex flex-wrap items-center justify-between gap-4 px-6 py-4">
          <div>
            <h1 className="text-xl font-semibold tracking-tight text-foreground">Signal2Spec</h1>
            <p className="text-xs uppercase tracking-wide text-zinc-500 dark:text-zinc-400">
              Prioritized requirements for product decisions
            </p>
          </div>
          <div className="flex items-center gap-3">
            <label className="flex items-center gap-2 text-sm text-zinc-700 dark:text-zinc-300">
              Scenario
              <select
                value={scenarioId}
                onChange={(e) => setScenarioId(e.target.value)}
                disabled={!scenarios}
                className="rounded-sm border border-zinc-300 bg-surface px-3 py-1.5 text-sm text-foreground focus:border-accent focus:outline-none dark:border-zinc-700"
              >
                {(scenarios ?? []).map((s) => (
                  <option key={s.id} value={s.id}>
                    {s.model_name} ({s.market})
                  </option>
                ))}
              </select>
            </label>
            <a
              href={getExportUrl(scenarioId)}
              target="_blank"
              rel="noopener noreferrer"
              className="rounded-sm bg-accent px-4 py-1.5 text-sm font-medium uppercase tracking-wide text-white hover:bg-accent-hover"
            >
              Export CSV
            </a>
            <ThemeToggle />
          </div>
        </div>
      </header>

      {/* Mitte: Ergebnis-Fenster, 2cm Abstand zu Rand, Top-Bar und Prompt-Leiste */}
      <main className="m-[2cm] flex flex-1 flex-col">
        <div className="border-t border-b border-zinc-200 bg-surface dark:border-zinc-800">
          {error && (
            <div className="m-4 rounded-md border border-rose-300 bg-rose-50 px-4 py-3 text-sm text-rose-800 dark:border-rose-800 dark:bg-rose-950 dark:text-rose-300">
              {error}
            </div>
          )}

          {!error && isLoading && <p className="p-4 text-sm text-zinc-500 dark:text-zinc-400">Loading…</p>}

          {!error && !isLoading && requirements !== null && requirements.length === 0 && (
            <p className="p-4 text-sm text-zinc-500 dark:text-zinc-400">No requirements for this scenario yet.</p>
          )}

          {!error && !isLoading && requirements !== null && requirements.length > 0 && (
            <table className="w-full text-left text-sm">
              <thead className="border-b border-zinc-200 bg-zinc-50 text-xs uppercase tracking-wide text-zinc-500 dark:border-zinc-800 dark:bg-zinc-900 dark:text-zinc-400">
                <tr>
                  <th className="px-4 py-3">Score</th>
                  <th className="px-4 py-3">Title</th>
                  <th className="px-4 py-3">Category</th>
                </tr>
              </thead>
              <tbody>
                {requirements.map((req) => (
                  <tr
                    key={req.id}
                    role="link"
                    tabIndex={0}
                    onClick={() => router.push(`/requirements/${req.id}`)}
                    onKeyDown={(e) => {
                      if (e.key === "Enter" || e.key === " ") {
                        e.preventDefault();
                        router.push(`/requirements/${req.id}`);
                      }
                    }}
                    className="cursor-pointer border-b border-zinc-100 last:border-0 hover:bg-accent/5 focus:bg-accent/5 focus:outline-none dark:border-zinc-800 dark:hover:bg-zinc-900 dark:focus:bg-zinc-900"
                  >
                    <td className="px-4 py-3">
                      <ScoreBar score={req.score} />
                    </td>
                    <td className="px-4 py-3 font-medium text-foreground">{req.title}</td>
                    <td className="px-4 py-3 text-zinc-700 dark:text-zinc-300">{categoryLabel(req.category)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </main>

      {/* Unten: Prompt-Eingabe, 1cm Abstand zum Rand unten, 2cm links/rechts */}
      <footer className="mx-[3cm] mb-[2cm] flex flex-col gap-2">
        {promptNote && <p className="text-xs text-zinc-500 dark:text-zinc-400">{promptNote}</p>}
        <div className="flex items-center gap-3">
          <input
            type="text"
            value={promptText}
            onChange={(e) => setPromptText(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") handlePromptSubmit();
            }}
            placeholder="Ask me your questions..."
            className="flex-1 rounded-sm border border-zinc-300 bg-surface px-4 py-4 text-sm text-foreground focus:border-accent focus:outline-none dark:border-zinc-700"
          />
          <button
            type="button"
            onClick={handlePromptSubmit}
            className="rounded-sm bg-accent px-5 py-4 text-sm font-medium uppercase tracking-wide text-white hover:bg-accent-hover"
          >
            Submit
          </button>
        </div>
      </footer>
    </div>
  );
}

/**
 * Horizontaler Balken für den Score (0-100) mit Zahl daneben, Akzentfarbe Blau
 * nach Design-Regel. Eigene Datei, weil Liste (D2) und Score-Wasserfall (D3)
 * dieselbe Balken-Optik brauchen.
 */
export function ScoreBar({ score }: { score: number }) {
  const width = Math.max(0, Math.min(100, score));
  return (
    <div className="flex items-center gap-2">
      <div className="h-2 w-28 overflow-hidden rounded-full bg-zinc-200 dark:bg-zinc-800">
        <div className="h-full rounded-full bg-accent" style={{ width: `${width}%` }} />
      </div>
      <span className="w-10 text-right text-sm font-medium text-foreground">
        {Math.round(score)}
      </span>
    </div>
  );
}

/**
 * Score-Wasserfall für die Detailseite (D3). Spiegelt die Formel aus
 * requirements_engine/scoring.py: score = Konfidenz(Evidenzstufe) * Summe(gewicht_i * faktor_i) * 100.
 * Die Konfidenzzahlen selbst (A=1.0 ... D=0.5) holen wir NICHT hierher, sondern rechnen den
 * Abzug aus Zwischensumme und Endscore zurück — sonst müssten zwei Stellen dieselbe Zahl pflegen.
 */
import type { EvidenceLevel, ScoreFactor } from "@/src/lib/api";

const FACTOR_ORDER = [
  "customer_pain",
  "reach",
  "satisfaction_gap",
  "competitive_pressure",
  "future_relevance",
  "effort_inverse",
] as const;

const FACTOR_LABELS: Record<string, string> = {
  customer_pain: "Customer pain",
  reach: "Reach",
  satisfaction_gap: "Satisfaction gap",
  competitive_pressure: "Competitive pressure",
  future_relevance: "Future relevance",
  effort_inverse: "Low effort",
};

const EVIDENCE_LABEL: Record<EvidenceLevel, string> = {
  A: "A · strong",
  B: "B · medium",
  C: "C · weak",
  D: "D · assumption",
};

function FactorRow({ label, factor }: { label: string; factor: ScoreFactor }) {
  // Balkenbreite relativ zum höchstmöglichen Beitrag dieses Faktors (weight * 100),
  // damit ein voll ausgeschöpfter Faktor immer einen vollen Balken zeigt.
  const maxContribution = Math.max(factor.weight * 100, 0.01);
  const width = Math.min(100, (factor.contribution / maxContribution) * 100);
  return (
    <div className="py-2">
      <div className="flex flex-wrap items-baseline justify-between gap-x-3 text-sm">
        <span className="font-medium text-[#0b1f3a] dark:text-zinc-100">{label}</span>
        <span className="text-zinc-500 dark:text-zinc-400">
          +{factor.contribution.toFixed(1)} pts
          <span className="ml-1 text-xs text-zinc-400 dark:text-zinc-500">
            ({factor.value.toFixed(2)} × {factor.weight.toFixed(2)} × 100)
          </span>
        </span>
      </div>
      <div className="mt-1 h-2 w-full overflow-hidden rounded-full bg-zinc-100 dark:bg-zinc-800">
        <div className="h-full rounded-full bg-accent" style={{ width: `${width}%` }} />
      </div>
      <p className="mt-1 text-xs text-zinc-500 dark:text-zinc-400">{factor.explanation}</p>
    </div>
  );
}

export function ScoreWaterfall({
  scoreBreakdown,
  evidenceLevel,
  finalScore,
}: {
  scoreBreakdown: Record<string, ScoreFactor>;
  evidenceLevel: EvidenceLevel;
  finalScore: number;
}) {
  const known = new Set<string>(FACTOR_ORDER);
  const orderedKeys = [
    ...FACTOR_ORDER.filter((key) => key in scoreBreakdown),
    ...Object.keys(scoreBreakdown).filter((key) => !known.has(key)),
  ];
  const subtotal = orderedKeys.reduce((sum, key) => sum + scoreBreakdown[key].contribution, 0);
  const deduction = Math.max(0, subtotal - finalScore);
  const keptPercent = subtotal > 0 ? Math.round((finalScore / subtotal) * 100) : 100;

  return (
    <div className="rounded-lg border border-zinc-200 bg-surface p-5 dark:border-zinc-800">
      <h2 className="text-sm font-semibold uppercase tracking-wide text-zinc-500 dark:text-zinc-400">Score breakdown</h2>
      <div className="mt-2 divide-y divide-zinc-100 dark:divide-zinc-800">
        {orderedKeys.map((key) => (
          <FactorRow key={key} label={FACTOR_LABELS[key] ?? key} factor={scoreBreakdown[key]} />
        ))}
      </div>

      <div className="mt-4 border-t border-dashed border-zinc-300 pt-3 dark:border-zinc-700">
        <div className="flex items-baseline justify-between text-sm">
          <span className="text-zinc-600 dark:text-zinc-400">Subtotal (all factors, full confidence)</span>
          <span className="font-medium text-[#0b1f3a] dark:text-zinc-100">{subtotal.toFixed(1)} pts</span>
        </div>
        {deduction > 0 && (
          <div className="mt-1 flex items-baseline justify-between text-sm">
            <span className="text-zinc-600 dark:text-zinc-400">
              Confidence deduction — evidence level {EVIDENCE_LABEL[evidenceLevel]} keeps {keptPercent}%
            </span>
            <span className="font-medium text-amber-700 dark:text-amber-400">-{deduction.toFixed(1)} pts</span>
          </div>
        )}
        <div className="mt-2 flex items-baseline justify-between border-t border-zinc-200 pt-2 text-base dark:border-zinc-800">
          <span className="font-semibold text-[#0b1f3a] dark:text-zinc-100">Final score</span>
          <span className="font-semibold text-[#0b1f3a] dark:text-zinc-100">{finalScore.toFixed(1)} / 100</span>
        </div>
      </div>
    </div>
  );
}
